# nMon Agent v2.0 - Windows\n# Features: Monitoring + Remote Control\n\nparam(\n    [string]$ServerKey,\n    [string]$Gateway,\n    [double]$Latitude = 0,\n    [double]$Longitude = 0\n)\n\n# Configuration\n$AgentDir = \"C:\\Program Files\\nMon\"\n$ConfigFile = \"$AgentDir\\config.json\"\n$Logfile = \"$AgentDir\\agent.log\"\n\n# Create directories\nif (!(Test-Path $AgentDir)) {\n    New-Item -ItemType Directory -Path $AgentDir -Force | Out-Null\n}\n\n# Functions\nfunction Write-Log {\n    param([string]$Message)\n    $timestamp = Get-Date -Format \"yyyy-MM-dd HH:mm:ss\"\n    \"$timestamp - $Message\" | Out-File -FilePath $Logfile -Append\n}\n\nfunction Get-Config {\n    if (Test-Path $ConfigFile) {\n        return Get-Content $ConfigFile | ConvertFrom-Json\n    }\n    return $null\n}\n\nfunction Save-Config {\n    param([hashtable]$Config)\n    $Config | ConvertTo-Json | Out-File -FilePath $ConfigFile\n}\n\n# Load or create config\n$config = Get-Config\nif ($config -and $ServerKey -eq \"\") {\n    $ServerKey = $config.ServerKey\n    $Gateway = $config.Gateway\n    $Latitude = $config.Latitude\n    $Longitude = $config.Longitude\n}\n\n# Save config\nSave-Config @{\n    ServerKey = $ServerKey\n    Gateway = $Gateway\n    Latitude = $Latitude\n    Longitude = $Longitude\n}\n\nWrite-Log \"Agent started\"\n\n#============\n# Remote Command Handler\n#============\n\nfunction Check-RemoteCommands {\n    $commandsFile = \"$AgentDir\\commands.json\"\n    \n    if (!(Test-Path $commandsFile)) {\n        return\n    }\n    \n    $commands = Get-Content $commandsFile | ConvertFrom-Json\n    \n    foreach ($cmd in $commands) {\n        if ($cmd.id -and $cmd.command) {\n            Execute-RemoteCommand -Id $cmd.id -Command $cmd.command\n        }\n    }\n    \n    # Clear processed commands\n    Remove-Item $commandsFile -Force\n}\n\nfunction Execute-RemoteCommand {\n    param(\n        [string]$Id,\n        [string]$Command\n    )\n    \n    Write-Log \"Executing remote command ID: $Id - $Command\"\n    \n    # Security: Check if command is allowed\n    if (!(Test-CommandAllowed -Command $Command)) {\n        Send-CommandResult -Id $Id -ExitCode 1 -Output \"Command not allowed: $Command\"\n        return\n    }\n    \n    try {\n        $output = Invoke-Expression $Command 2>&1 | Out-String\n        $exitCode = $LASTEXITCODE\n        \n        if ($exitCode -eq $null) {\n            $exitCode = 0\n        }\n    }\n    catch {\n        $output = $_.Exception.Message\n        $exitCode = 1\n    }\n    \n    Send-CommandResult -Id $Id -ExitCode $exitCode -Output $output\n}\n\nfunction Test-CommandAllowed {\n    param([string]$Command)\n    \n    # List of allowed commands\n    $allowedCommands = @(\n        \"Get-Process\",\n        \"Get-Service\",\n        \"Get-ChildItem\",\n        \"Get-Content\",\n        \"Get-WmiObject\",\n        \"Get-CimInstance\",\n        \"Test-Connection\",\n        \"Test-NetConnection\",\n        \"Get-NetAdapter\",\n        \"Get-NetIPAddress\",\n        \"Get-Disk\",\n        \"Get-Partition\",\n        \"Get-Volume\",\n        \"Get-HotFix\",\n        \"Get-WindowsUpdate\",\n        \"Get-EventLog\",\n        \"Get-WinEvent\",\n        \"Get-Clipboard\",\n        \"Get-Date\",\n        \"Get-Location\",\n        \"hostname\",\n        \"ipconfig\",\n        \"netstat\",\n        \"tasklist\",\n        \"systeminfo\"\n    )\n    \n    # Check if command starts with any allowed command\n    foreach ($allowed in $allowedCommands) {\n        if ($Command -match \"^$allowed\") {\n            return $true\n        }\n    }\n    \n    return $false\n}\n\nfunction Send-CommandResult {\n    param(\n        [string]$Id,\n        [int]$ExitCode,\n        [string]$Output\n    )\n    \n    # Encode output\n    $encodedOutput = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($Output))\n    \n    # Send result to server\n    $body = @{\n        action = \"command_result\"\n        cmd_id = $Id\n        exit_code = $ExitCode\n        output = $encodedOutput\n        serverkey = $ServerKey\n    }\n    \n    try {\n        Invoke-RestMethod -Uri $Gateway -Method Post -Body $body\n    }\n    catch {\n        Write-Log \"Error sending command result: $_\"\n    }\n}\n\n#============\n# Main Agent\n#============\n\n# Check for remote commands\nCheck-RemoteCommands\n\n# System Info\n$os = Get-CimInstance Win32_OperatingSystem\n$cpu = Get-CimInstance Win32_Processor\n$disk = Get-CimInstance Win32_LogicalDisk -Filter \"DriveType=3\"\n$net = Get-NetAdapter | Where-Object {$_.Status -eq \"Up\"}\n\n# Build POST data\n$POST = @{}\n\n# Agent version\n$POST[\"agent_version\"] = \"2.0\"\n\n# Server key\n$POST[\"serverkey\"] = $ServerKey\n\n# Gateway\n$POST[\"gateway\"] = $Gateway\n\n# Hostname\n$POST[\"hostname\"] = $env:COMPUTERNAME\n\n# Kernel\n$POST[\"kernel\"] = $os.Version\n\n# Time\n$POST[\"time\"] = [int][double]::Parse((Get-Date -UFormat %s))\n\n# OS\n$POST[\"os\"] = $os.Caption\n\n# OS Arch\n$POST[\"os_arch\"] = $os.OSArchitecture\n\n# CPU Model\n$POST[\"cpu_model\"] = $cpu.Name\n\n# CPU Cores\n$POST[\"cpu_cores\"] = $cpu.NumberOfCores\n\n# CPU Speed\n$POST[\"cpu_speed\"] = $cpu.MaxClockSpeed\n\n# CPU Load (JSON format for Windows)\n$cpuLoad = Get-CimInstance Win32_Processor | Select-Object LoadPercentage\n$POST[\"cpu_load\"] = @{currentload = $cpuLoad.LoadPercentage; avgload = $cpuLoad.LoadPercentage} | ConvertTo-Json\n\n# Disks (JSON format)\n$diskInfo = @()\nforeach ($d in $disk) {\n    $diskInfo += @{\n        filesystem = $d.DeviceID\n        size = [math]::Round($d.Size / 1MB)\n        used = [math]::Round(($d.Size - $d.FreeSpace) / 1MB)\n        available = [math]::Round($d.FreeSpace / 1MB)\n        percentage = [math]::Round((($d.Size - $d.FreeSpace) / $d.Size) * 100)\n        mount = $d.DeviceID\n    }\n}\n$POST[\"filesystems\"] = $diskInfo | ConvertTo-Json\n\n# RAM\n$ramTotal = [math]::Round($os.TotalVisibleMemorySize / 1MB)\n$ramFree = [math]::Round($os.FreePhysicalMemory / 1MB)\n$ramUsed = $ramTotal - $ramFree\n\n$POST[\"ram_total\"] = $ramTotal\n$POST[\"ram_free\"] = $ramFree\n$POST[\"ram_usage\"] = $ramUsed\n\n# Network (JSON format)\n$netStats = @()\nforeach ($adapter in $net) {\n    $stats = Get-NetAdapterStatistics -Name $adapter.Name\n    $netStats += @{\n        iface = $adapter.Name\n        rx = $stats.ReceivedBytes\n        tx = $stats.SentBytes\n        rx_sec = 0\n        tx_sec = 0\n    }\n}\n$POST[\"net_stats\"] = $netStats | ConvertTo-Json\n$POST[\"net_interfaces\"] = $netStats | ConvertTo-Json\n\n# IPv4 Addresses\n$ipv4 = Get-NetIPAddress -AddressFamily IPv4 | Where-Object {$_.IPAddress -ne \"127.0.0.1\"}\n$ipv4Addresses = @()\nforeach ($ip in $ipv4) {\n    $ipv4Addresses += \"$($ip.InterfaceAlias),$($ip.IPAddress)\"\n}\n$POST[\"ipv4_addresses\"] = $ipv4Addresses -join \";\"\n\n# Uptime\n$uptime = (Get-Date) - $os.LastBootUpTime\n$POST[\"uptime\"] = $uptime.TotalSeconds\n\n# Location\nif ($Latitude -ne 0 -and $Longitude -ne 0) {\n    $POST[\"lat\"] = $Latitude\n    $POST[\"lng\"] = $Longitude\n}\n\n# Convert to URL-encoded string\n$postData = @()\nforeach ($key in $POST.Keys) {\n    $postData += \"$key=$([System.Uri]::EscapeDataString($POST[$key]))\"\n}\n\n$body = $postData -join \"&\"\n\n# Send data\ntry {\n    $response = Invoke-RestMethod -Uri $Gateway -Method Post -Body $body -ContentType \"application/x-www-form-urlencoded\"\n    Write-Log \"Data sent successfully\"\n}\ncatch {\n    Write-Log \"Error sending data: $_\"\n}\n\nWrite-Log \"Agent completed\"\n